    15	        LocalDate checkIn,
    16	        LocalDate checkOut,
    17	        int guests,
    18	        String ratePlan,
    19	        int nights,
    20	        BigDecimal subtotal,
    21	        BigDecimal discount,
    22	        BigDecimal total,
    23	        ReservationStatus status,
    24	        BigDecimal amountPaid,
    25	        BigDecimal refund) {
    26	
    27	    public Reservation confirm() {
    28	        require(status == ReservationStatus.PENDING, "Só é possível confirmar uma reserva pendente");
    29	        return new Reservation(id, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan,
    30	                nights, subtotal, discount, total, ReservationStatus.CONFIRMED, total, refund);
    31	    }
    32	
    33	    public Reservation startStay() {
    34	        require(status == ReservationStatus.CONFIRMED, "Só é possível fazer check-in de uma reserva confirmada");
    35	        return withStatus(ReservationStatus.CHECKED_IN);
    36	    }
    37	
