    51	    public Reservation withId(long newId) {
    52	        return new Reservation(newId, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan,
    53	                nights, subtotal, discount, total, status, amountPaid, refund);
