     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.temporal.ChronoUnit;
     6	
     7	/** O que um plano de tarifa precisa saber para precificar e validar uma estadia. */
     8	public record Stay(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
     9	    private static final BigDecimal HIGH_SEASON = new BigDecimal("1.20");
    10	
    11	    public int nights() {
    12	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    13	    }
    14	
    15	    /** Soma das noites, cada uma arredondada, com a alta temporada aplicada. */
    16	    public BigDecimal nightsTotal() {
    17	        BigDecimal sum = Money.ZERO;
    18	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    19	            BigDecimal price = Season.isHigh(night)
    20	                    ? Money.round(room.nightlyRate().multiply(HIGH_SEASON))
    21	                    : room.nightlyRate();
    22	            sum = sum.add(price);
    23	        }
    24	        return sum;
    25	    }
    26	}
