     1	package br.com.marealta.infra;
     2	
     3	import java.sql.Connection;
     4	import java.sql.DriverManager;
     5	import java.sql.SQLException;
     6	import java.sql.Statement;
     7	
     8	public class Database {
     9	    @FunctionalInterface
    10	    public interface Work<T> {
    11	        T run(Connection c) throws SQLException;
    12	    }
    13	
    14	    private final String url, user, password;
    15	
    16	    public Database(String url, String user, String password) {
    17	        this.url = url;
    18	        this.user = user;
    19	        this.password = password;
    20	    }
    21	
    22	    public void migrate() {
    23	        SQLException last = null;
    24	        for (int attempt = 0; attempt < 30; attempt++) {
    25	            try {
    26	                inTransaction(c -> {
    27	                    try (Statement st = c.createStatement()) {
    28	                        st.execute("""
    29	                                CREATE TABLE IF NOT EXISTS reservations (
    30	                                  id BIGSERIAL PRIMARY KEY,
    31	                                  room_number INT NOT NULL,
    32	                                  guest_name TEXT NOT NULL,
    33	                                  guest_email TEXT NOT NULL,
    34	                                  guest_cpf TEXT NOT NULL,
    35	                                  check_in DATE NOT NULL,
    36	                                  check_out DATE NOT NULL,
    37	                                  guests INT NOT NULL,
    38	                                  rate_plan TEXT NOT NULL,
    39	                                  nights INT NOT NULL,
    40	                                  subtotal NUMERIC(12,2) NOT NULL,
    41	                                  discount NUMERIC(12,2) NOT NULL,
    42	                                  total NUMERIC(12,2) NOT NULL,
    43	                                  status TEXT NOT NULL,
    44	                                  amount_paid NUMERIC(12,2) NOT NULL,
    45	                                  refund NUMERIC(12,2))""");
    46	                        st.execute("""
    47	                                CREATE TABLE IF NOT EXISTS messages (
    48	                                  id BIGSERIAL PRIMARY KEY,
    49	                                  channel TEXT NOT NULL,
    50	                                  recipient TEXT NOT NULL,
    51	                                  subject TEXT NOT NULL,
    52	                                  body TEXT NOT NULL)""");
    53	                    }
    54	                    return null;
    55	                });
    56	                return;
    57	            } catch (RuntimeException e) {
    58	                if (!(e.getCause() instanceof SQLException se)) throw e;
    59	                last = se;
    60	                try { Thread.sleep(1000); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); }
    61	            }
    62	        }
    63	        throw new IllegalStateException("Banco indisponível", last);
    64	    }
    65	
    66	    public <T> T inTransaction(Work<T> work) {
    67	        try (Connection c = DriverManager.getConnection(url, user, password)) {
    68	            c.setAutoCommit(false);
    69	            try {
    70	                T result = work.run(c);
    71	                c.commit();
    72	                return result;
    73	            } catch (SQLException | RuntimeException e) {
    74	                c.rollback();
    75	                throw e;
    76	            }
    77	        } catch (SQLException e) {
    78	            throw new IllegalStateException(e.getMessage(), e);
    79	        }
    80	    }
    81	}
