    28	
    29	    public boolean hasConflict(Connection c, int roomNumber, LocalDate in, LocalDate out) throws SQLException {
    30	        try (PreparedStatement ps = c.prepareStatement(
    31	                "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    32	                        + "AND check_in < ? AND check_out > ? LIMIT 1")) {
    33	            ps.setInt(1, roomNumber);
    34	            ps.setObject(2, out);
    35	            ps.setObject(3, in);
    36	            try (ResultSet rs = ps.executeQuery()) {
    37	                return rs.next();
    38	            }
    39	        }
    40	    }
