    42	    public Reservation insert(Connection c, Reservation r) throws SQLException {
    43	        try (PreparedStatement ps = c.prepareStatement(
    44	                "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    45	                        + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund) "
    46	                        + "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id")) {
    47	            ps.setInt(1, r.roomNumber());
    48	            ps.setString(2, r.guestName());
    49	            ps.setString(3, r.guestEmail());
    50	            ps.setString(4, r.guestCpf());
    51	            ps.setObject(5, r.checkIn());
    52	            ps.setObject(6, r.checkOut());
    53	            ps.setInt(7, r.guests());
    54	            ps.setString(8, r.ratePlan());
    55	            ps.setInt(9, r.nights());
    56	            ps.setBigDecimal(10, r.subtotal());
    57	            ps.setBigDecimal(11, r.discount());
    58	            ps.setBigDecimal(12, r.total());
    59	            ps.setString(13, r.status().name());
    60	            ps.setBigDecimal(14, r.amountPaid());
    61	            setNullable(ps, 15, r.refund());
    62	            try (ResultSet rs = ps.executeQuery()) {
    63	                rs.next();
