    80	    public Optional<Reservation> find(Connection c, long id, boolean forUpdate) throws SQLException {
    81	        try (PreparedStatement ps = c.prepareStatement(
    82	                "SELECT " + COLUMNS + " FROM reservations WHERE id = ?" + (forUpdate ? " FOR UPDATE" : ""))) {
    83	            ps.setLong(1, id);
    84	            try (ResultSet rs = ps.executeQuery()) {
    85	                return rs.next() ? Optional.of(map(rs)) : Optional.empty();
    86	            }
    87	        }
    88	    }
