    90	    /** Reservas com check_in <= to e check_out > from, na ordem de entrada e número. */
    91	    public List<Reservation> findOverlapping(Connection c, LocalDate from, LocalDate toExclusive) throws SQLException {
    92	        return query(c, "check_in < ? AND check_out > ?", toExclusive, from);
    93	    }
    94	
    95	    public List<Reservation> findStartingBetween(Connection c, LocalDate from, LocalDate toExclusive)
    96	            throws SQLException {
