    99	
   100	    private List<Reservation> query(Connection c, String where, LocalDate a, LocalDate b) throws SQLException {
   101	        try (PreparedStatement ps = c.prepareStatement(
   102	                "SELECT " + COLUMNS + " FROM reservations WHERE " + where + " ORDER BY check_in, id")) {
   103	            ps.setObject(1, a);
   104	            ps.setObject(2, b);
   105	            List<Reservation> list = new ArrayList<>();
   106	            try (ResultSet rs = ps.executeQuery()) {
   107	                while (rs.next()) list.add(map(rs));
   108	            }
