   122	                rs.getString("guest_email"), rs.getString("guest_cpf"),
   123	                rs.getObject("check_in", LocalDate.class), rs.getObject("check_out", LocalDate.class),
   124	                rs.getInt("guests"), rs.getString("rate_plan"), rs.getInt("nights"),
   125	                rs.getBigDecimal("subtotal"), rs.getBigDecimal("discount"), rs.getBigDecimal("total"),
   126	                ReservationStatus.valueOf(rs.getString("status")),
