     9	import java.math.BigDecimal;
    10	import java.time.LocalDate;
    11	import java.time.YearMonth;
    12	import java.util.Comparator;
    13	import java.util.List;
    14	
    15	public class ReportService {
    16	    private final Database db;
    17	    private final ReservationRepository reservations;
    18	
    19	    public ReportService(Database db, ReservationRepository reservations) {
    20	        this.db = db;
    21	        this.reservations = reservations;
    22	    }
    23	
    24	    public String occupancy(LocalDate night) {
    25	        List<Reservation> occupying = db.inTransaction(c -> reservations.findOverlapping(c, night, night.plusDays(1)))
    26	                .stream()
    27	                .filter(r -> r.status().isPaid())
    28	                .sorted(Comparator.comparingInt(Reservation::roomNumber))
    29	                .toList();
    30	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    31	        for (Reservation r : occupying) {
    32	            Room room = Rooms.find(r.roomNumber()).orElseThrow();
    33	            csv.append(room.number()).append(',').append(room.type()).append(',').append(r.id()).append(',')
    34	                    .append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
    35	        }
    36	        return csv.append("total,").append(occupying.size()).append('/').append(Rooms.ALL.size()).append('\n')
    37	                .toString();
    38	    }
    39	
    40	    public String revenue(YearMonth month) {
    41	        List<Reservation> kept = db.inTransaction(
    42	                        c -> reservations.findStartingBetween(c, month.atDay(1), month.plusMonths(1).atDay(1)))
    43	                .stream()
    44	                .filter(r -> kept(r).signum() > 0)
    45	                .toList();
    46	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    47	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
    48	        for (Reservation r : kept) {
    49	            BigDecimal amount = kept(r);
    50	            sum = sum.add(amount);
    51	            csv.append(r.id()).append(',').append(r.roomNumber()).append(',').append(r.checkIn()).append(',')
    52	                    .append(r.checkOut()).append(',').append(r.status()).append(',').append(amount.toPlainString())
    53	                    .append('\n');
    54	        }
    55	        return csv.append("total,").append(sum.toPlainString()).append('\n').toString();
    56	    }
    57	
    58	    /** Dinheiro que fica com a pousada: o que foi pago menos o que foi devolvido. */
    59	    private static BigDecimal kept(Reservation r) {
    60	        return r.refund() == null ? r.amountPaid() : r.amountPaid().subtract(r.refund());
    61	    }
    62	}
