    25	    private final MessageRepository messages;
    26	    private final RatePlans plans;
    27	
    28	    public ReservationService(Database db, ReservationRepository reservations, MessageRepository messages,
    29	                              RatePlans plans) {
    30	        this.db = db;
    31	        this.reservations = reservations;
    32	        this.messages = messages;
    33	        this.plans = plans;
    34	    }
    35	
    36	    public Reservation create(ReservationRequest req) {
    37	        Room room = Rooms.find(req.roomNumber())
    38	                .orElseThrow(() -> new DomainException(404, "ROOM_NOT_FOUND", "Quarto não encontrado"));
    39	        if (req.guests() > room.capacity()) {
    40	            throw new DomainException(422, "CAPACITY_EXCEEDED", "O quarto comporta até " + room.capacity() + " pessoas");
    41	        }
    42	        RatePlan plan = plans.get(req.ratePlan());
    43	        Quote quote = plan.quote(new Stay(room, req.checkIn(), req.checkOut(), req.companyCode()));
    44	        Reservation draft = new Reservation(0, room.number(), req.guestName(), req.guestEmail(), req.guestCpf(),
    45	                req.checkIn(), req.checkOut(), req.guests(), plan.code(), quote.nights(), quote.subtotal(),
    46	                quote.discount(), quote.total(), ReservationStatus.PENDING, Money.ZERO, null);
    47	        return db.inTransaction(c -> {
    48	            reservations.lockRoom(c, room.number());
    49	            if (reservations.hasConflict(c, room.number(), req.checkIn(), req.checkOut())) {
    50	                throw new DomainException(409, "ROOM_UNAVAILABLE", "Quarto já reservado em alguma das noites");
    51	            }
    52	            return reservations.insert(c, draft);
    53	        });
    54	    }
    55	
    56	    public Reservation get(long id) {
    57	        return db.inTransaction(c -> reservations.find(c, id, false).orElseThrow(ReservationService::notFound));
    58	    }
    59	
    60	    public Reservation confirm(long id) {
    61	        return db.inTransaction(c -> {
    62	            Reservation confirmed = reservations.find(c, id, true).orElseThrow(ReservationService::notFound).confirm();
    63	            reservations.update(c, confirmed);
    64	            messages.save(c, ConfirmationEmail.of(confirmed, Rooms.find(confirmed.roomNumber()).orElseThrow()));
    65	            return confirmed;
    66	        });
    67	    }
    68	
    69	    public Reservation cancel(long id) {
    70	        return transition(id, r -> r.cancel(plans.get(r.ratePlan())));
    71	    }
    72	
    73	    public Reservation checkIn(long id) {
    74	        return transition(id, Reservation::startStay);
    75	    }
