    92	
    93	    private Reservation transition(long id, UnaryOperator<Reservation> change) {
    94	        return db.inTransaction(c -> {
    95	            Reservation updated = change.apply(reservations.find(c, id, true).orElseThrow(ReservationService::notFound));
    96	            reservations.update(c, updated);
