     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.DomainException;
     4	import br.com.marealta.service.ReservationRequest;
     5	import com.fasterxml.jackson.core.JsonProcessingException;
     6	import com.fasterxml.jackson.databind.JsonNode;
     7	import com.fasterxml.jackson.databind.ObjectMapper;
     8	
     9	import java.time.LocalDate;
    10	import java.time.YearMonth;
    11	import java.time.format.DateTimeParseException;
    12	
    13	final class RequestParser {
    14	    private RequestParser() {}
    15	
    16	    static ReservationRequest reservation(ObjectMapper mapper, String body) {
    17	        JsonNode json;
    18	        try {
    19	            json = mapper.readTree(body);
    20	        } catch (JsonProcessingException e) {
    21	            throw DomainException.invalid("Corpo da requisição não é um JSON válido");
    22	        }
    23	        if (json == null || !json.isObject()) throw DomainException.invalid("Corpo da requisição deve ser um objeto JSON");
    24	
    25	        JsonNode roomNode = json.get("roomNumber");
    26	        JsonNode guestsNode = json.get("guests");
    27	        if (roomNode == null || !roomNode.isIntegralNumber()) throw DomainException.invalid("roomNumber é obrigatório");
    28	        if (guestsNode == null || !guestsNode.isIntegralNumber()) throw DomainException.invalid("guests é obrigatório");
    29	        int guests = guestsNode.asInt();
    30	        if (guests < 1) throw DomainException.invalid("É preciso pelo menos um hóspede");
    31	
    32	        LocalDate checkIn = date(json, "checkIn");
    33	        LocalDate checkOut = date(json, "checkOut");
    34	        if (!checkOut.isAfter(checkIn)) throw DomainException.invalid("A saída deve ser depois da entrada");
    35	
    36	        JsonNode company = json.get("companyCode");
    37	        String companyCode = company != null && company.isTextual() ? company.asText() : null;
    38	
    39	        return new ReservationRequest(roomNode.asInt(), text(json, "guestName"), text(json, "guestEmail"),
    40	                text(json, "guestCpf"), checkIn, checkOut, guests, text(json, "ratePlan"), companyCode);
    41	    }
    42	
    43	    static LocalDate date(String value, String field) {
    44	        try {
    45	            return LocalDate.parse(value);
    46	        } catch (DateTimeParseException | NullPointerException e) {
    47	            throw DomainException.invalid(field + " inválida, use o formato AAAA-MM-DD");
    48	        }
    49	    }
    50	
    51	    static YearMonth month(String value) {
    52	        try {
    53	            return YearMonth.parse(value);
    54	        } catch (DateTimeParseException | NullPointerException e) {
    55	            throw DomainException.invalid("month inválido, use o formato AAAA-MM");
    56	        }
    57	    }
    58	
    59	    private static LocalDate date(JsonNode json, String field) {
    60	        return date(text(json, field), field);
    61	    }
    62	
    63	    private static String text(JsonNode json, String field) {
    64	        JsonNode node = json.get(field);
    65	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    66	            throw DomainException.invalid(field + " é obrigatório");
    67	        }
    68	        return node.asText();
    69	    }
    70	}
